        return {"passed": False, "message": f"File exists but is empty: {filepath}"}

    return {"passed": True, "message": "File exists and is non-empty"}

def check_csv_structure(filepath):
    """Check if CSV has valid headers."""
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            content = f.read()

        # Check if file is empty
        if len(content.strip()) == 0:
            return {"passed": False, "message": "File exists but is empty"}

        # Read first line to check headers
        lines = content.strip().split('\n')
        if len(lines) < 2:
            return {"passed": False, "message": "CSV file has no headers"}

        headers = lines[0].strip()

        # Check for required columns in each file
        required_columns = {
            "t01_selected_indicators": ["indicator_id", "indicator_name", "theme", "justification", "expected_direction"],
            "t05_clean_stops": ["stop_id", "stop_name", "stop_lat", "stop_lon"],
            "t08_pois_clean": ["qid", "label", "poi_type", "latitude", "longitude", "source"],
            "t10_accessibility_scores": ["qid", "label", "poi_type", "distance_m", "n_departures", "n_routes", "accessibility_score"],
            "t13_city_clusters": ["city_id", "city_name", "year", "cluster_id"]
        }

        expected_columns = required_columns.get(filepath, [])

        # Check if all required columns exist
        for col in expected_columns:
            if col not in headers:
                return {"passed": False, "message": f"Missing required column: {col}"}

        return {"passed": True, "message": "CSV structure is valid"}
    except Exception as e:
        return {"passed": False, "message": f"Error reading file: {str(e)}"}

def check_csv_data_integrity(filepath):
    """Check basic data integrity in CSV."""
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            lines = f.readlines()

        if len(lines) < 2:
            return {"passed": False, "message": "CSV file has no data rows"}

        # Check that first row has expected number of columns
        headers = lines[0].strip().split(',')

        for col in headers:
            if col in filepath:  # Only check columns in the file
                pass  # Just verify headers are present

        return {"passed": True, "message": "Data integrity check passed"}
    except Exception as e:
        return {"passed": False, "message": f"Error checking data: {str(e)}"}

def run_checks():
    """Run all validation checks."""
    checks_results = []

    for output_file, check_config in CHECKS.items():
        filepath = check_config["path"]
        result = check_file_exists(filepath)
        checks_results.append(result)

        if result["passed"]:
            checks_results.append({"check_name": check_config["check_name"], "passed": True, "message": result["message"]})
        else:
            checks_results.append({"check_name": check_config["check_name"], "passed": False, "message": result["message"]})

    # Write results to JSON file
    output_file_path = os.path.join(SRC_DIR, "validate_outputs.py")
    output_file = open(output_file_path, 'w', encoding='utf-8')
    json_output = json.dumps(checks_results, indent=2)
    output_file.write(json_output)
    output_file.close()

    return checks_results

if __name__ == "__main__":
    print("Running validation checks...")
    results = run_checks()

    # Print summary
    passed_count = sum(1 for r in results if r["passed"])
    failed_count = len(results) - passed_count

    print(f"Validation complete. Passed: {passed_count}/{len(results)}")

    # Check if output file was created
    if os.path.exists(SRC_DIR + "/validate_outputs.py"):
        print("Output file created successfully.")
    else:
        print("Error: Output file was not created.")
        sys.exit(1)
